-- ── Validazione (eseguita dopo tutti gli INSERT) ──────────────────────────────
DO $$
DECLARE
  v_empty      integer;
  v_invalid    integer;
  v_wrong_srid integer;
  v_zero_area  integer;
  v_munis      integer;
  v_sectors    integer;
BEGIN
  SELECT COUNT(*) INTO v_empty
    FROM public.map_sectors WHERE service_type = 'd2d' AND ST_IsEmpty(geometry);
  SELECT COUNT(*) INTO v_invalid
    FROM public.map_sectors WHERE service_type = 'd2d' AND NOT ST_IsValid(geometry);
  SELECT COUNT(*) INTO v_wrong_srid
    FROM public.map_sectors WHERE service_type = 'd2d' AND ST_SRID(geometry) != 4326;
  SELECT COUNT(*) INTO v_zero_area
    FROM public.map_sectors
    WHERE service_type = 'd2d'
      AND round((ST_Area(geometry::geography) / 1e6)::numeric, 6) <= 0;
  SELECT COUNT(DISTINCT municipality_code), COUNT(*)
    INTO v_munis, v_sectors
    FROM public.map_sectors WHERE service_type = 'd2d';
  RAISE NOTICE '── Migration 014 — Riepilogo validazione ─────────────────────────';
  RAISE NOTICE 'Comuni processati  : %', v_munis;
  RAISE NOTICE 'Settori generati   : %', v_sectors;
  RAISE NOTICE 'Geometrie vuote    : % (atteso 0)', v_empty;
  RAISE NOTICE 'Geometrie invalide : % (atteso 0)', v_invalid;
  RAISE NOTICE 'SRID errati        : % (atteso 0)', v_wrong_srid;
  RAISE NOTICE 'Area zero          : % (atteso 0)', v_zero_area;
  IF v_empty      > 0 THEN RAISE EXCEPTION 'Trovate % geometrie vuote',            v_empty;      END IF;
  IF v_invalid    > 0 THEN RAISE EXCEPTION 'Trovate % geometrie non valide (ST_IsValid)', v_invalid; END IF;
  IF v_wrong_srid > 0 THEN RAISE EXCEPTION '% geometrie con SRID != 4326',         v_wrong_srid; END IF;
  IF v_zero_area  > 0 THEN RAISE EXCEPTION '% settori con area_km2 = 0',           v_zero_area;  END IF;
  IF v_munis < 1400   THEN RAISE EXCEPTION 'Troppo pochi comuni: % (attesi ~1500)', v_munis;      END IF;
  RAISE NOTICE 'Validazione SUPERATA ✓';
END;
$$;

